`,c.jsx(n.p,{children:"All intellectual property rights in materials produced by or under the authority of the International Organization for Identity Documents vest in the Organization, in accordance with Article 42 of the Charter and the Convention on the Protection of the Intellectual Property of the International Organization for Identity Documents."}),`
`,c.jsx(n.h2,{children:"Governing Instrument"}),`
`,c.jsxs(n.p,{children:["The ",c.jsx(n.a,{href:"/legal/registry#ip-convention",children:"Convention on the Protection of the Intellectual Property of the International Organization for Identity Documents"})," establishes the comprehensive framework for the ownership, protection, licensing, dissemination, and enforcement of all intellectual property of the Organization."]}),`
`,c.jsxs(n.p,{children:["The Convention is a voluntary treaty open to signature and accession by all States and intergovernmental organizations, whether or not they are Contracting Parties to the Charter. It entered into force on the thirtieth day after the deposit of the third instrument of ratification or accession. Current treaty status is maintained in the ",c.jsx(n.a,{href:"/legal/registry#treaty-status",children:"Legal Affairs Registry"}),"."]}),`
`,c.jsx(n.h2,{children:"What Constitutes OIDI Intellectual Property"}),`
`,c.jsx(n.p,{children:"Intellectual property of the Organization includes all works, inventions, databases, compilations, designs, trademarks, service marks, logos, names, domain names, software, algorithms, technical drawings, and other creations of the mind, in any medium, produced by or under the authority of the Organization."}),`
`,c.jsx(n.p,{children:"OIDI materials, the principal category of the Organization's intellectual property, include all standards, recommended practices, technical specifications, guidelines, reports, studies, publications, training materials, databases, and software produced by the Organization."}),`
`,c.jsx(n.p,{children:"The name, acronyms, emblem, and logo of the Organization are protected marks. No person or entity may use them without the prior written authorization of the General Secretariat."}),`
`,c.jsx(n.h2,{children:"Ownership and Assignment"}),`
`,c.jsx(n.p,{children:"All officials, experts, consultants, and contractors who produce intellectual property in connection with the work of the Organization assign, and are deemed to have assigned, all rights therein to the Organization. Terms of engagement include appropriate assignment provisions."}),`
`,c.jsx(n.p,{children:"Contracting Parties that contribute materials, data, or expertise grant the Organization a perpetual, irrevocable, worldwide, royalty-free licence to use, reproduce, modify, and distribute such contributions for the purposes of the Organization's work. The Organization acknowledges authorship of contributors where practicable."}),`
`,c.jsx(n.h2,{children:"Licensing Policy"}),`
`,c.jsx(n.p,{children:"The General Secretariat maintains a licensing policy designed to achieve the widest possible dissemination of standards and related materials, consistent with the financial sustainability of the Organization. The policy provides for:"}),`
`,c.jsxs(n.ul,{children:[`
`,c.jsxs(n.li,{children:[c.jsx(n.strong,{children:"Free access"}),": The texts of all International Standards of the Organization are made available to Contracting Parties free of charge;"]}),`
`,c.jsxs(n.li,{children:[c.jsx(n.strong,{children:"Preferential access for developing countries"}),": Developing countries receive preferential access to OIDI materials;"]}),`
`,c.jsxs(n.li,{children:[c.jsx(n.strong,{children:"Academic and research access"}),": Academic and research institutions receive access on favourable terms;"]}),`
`,c.jsxs(n.li,{children:[c.jsx(n.strong,{children:"Commercial licences"}),": Commercial use of OIDI materials is subject to a commercial licence issued by the General Secretariat."]}),`
`]}),`
`,c.jsx(n.p,{children:"The licensing policy prohibits the modification of OIDI materials without the written authorization of the General Secretariat, and requires that any reproduction or distribution is accurate and complete."}),`
`,c.jsx(n.p,{children:"Revenue generated from the licensing of OIDI materials constitutes income of the Organization within the meaning of Article 52 of the Charter."}),`
`,c.jsx(n.h2,{children:"Permissions Procedure"}),`
`,c.jsx(n.p,{children:"Requests for permission to reproduce, translate, adapt, or otherwise use OIDI materials should be addressed in writing to the Office of Legal Affairs, for the attention of the General Secretariat."}),`
`,c.jsx(n.p,{children:"A permissions request should include, inter alia:"}),`
`,c.jsxs(n.ol,{children:[`
`,c.jsx(n.li,{children:"The identity and contact details of the requester;"}),`
`,c.jsx(n.li,{children:"A precise description of the OIDI material to be used, including the title, registration number (where known), and relevant sections or elements;"}),`
`,c.jsx(n.li,{children:"The purpose and nature of the intended use (academic, commercial, governmental, or other);"}),`
`,c.jsx(n.li,{children:"The form and medium of reproduction or distribution;"}),`
`,c.jsx(n.li,{children:"The territory or jurisdiction in which the material will be used or distributed;"}),`
`,c.jsx(n.li,{children:"The proposed duration of use."}),`
`]}),`
`,c.jsx(n.p,{children:"The General Secretariat will respond to permissions requests within a reasonable time. Authorization, where granted, will be provided in writing and will specify the terms and conditions of use."}),`
`,c.jsxs(n.p,{children:["Requests may be submitted through the formal contact channels set out under ",c.jsx(n.a,{href:"/legal",children:"Office Overview"})," and ",c.jsx(n.a,{href:"/legal/procedures",children:"Public Procedures"}),"."]}),`
`,c.jsx(n.h2,{children:"Enforcement"}),`
`,c.jsx(n.p,{children:"Unauthorized use, reproduction, modification, or distribution of OIDI materials constitutes an infringement of the Organization's intellectual property rights. The General Secretariat takes all appropriate measures to enforce these rights, including legal proceedings in the courts of Contracting Parties."}),`
`,c.jsx(n.p,{children:"The unauthorized reproduction or use of the Organization's standards, certifications, or assessments in connection with identity documents is treated as a matter of particular gravity. Contracting Parties are obligated under the Convention to take such measures as are necessary under their domestic law to prevent and punish such conduct."}),`
`,c.jsx(n.hr,{}),`
