`,c.jsx(n.h2,{children:"Formal Contact"}),`
`,c.jsx(n.p,{children:"All formal communications to the Office of Legal Affairs shall be addressed in writing to the Secretary-General of the International Organization for Identity Documents, for the attention of the Office of Legal Affairs."}),`
`,c.jsx(n.p,{children:"Correspondence may be submitted by post to the seat of the Organization, or electronically through the official contact channels published on this website."}),`
